 * Parses a `process.argv`-style array into the shape needed for shell
 * completion.
 *
 * `process.argv` for a completion invocation looks like:
 *   ['node', '/path/to/nx', 'nx', 'run', 'my-app:bui']
 * or when the shell forwards the words without the script name:
 *   ['node', '/path/to/nx', 'run', 'my-app:bui']
 *
 * We always strip the first two entries (the node runtime and the nx binary
 * path). We then strip a single leading `nx` token if the shell forwarded the
 * script name as the first word. What remains are the user-supplied shell
 * tokens that we want to complete.
 *
 * @returns `null` when there are no user-supplied tokens to complete.
 */
export function parseCompletionArgs(argv: string[]): {
  tokens: string[];
  current: string;
  previousToken: string;
} | null {
  // Strip the node runtime and the nx binary path.
  let tokens = argv.slice(2);

  // Strip a leading 'nx' script-name token if the shell forwarded it.
  if (tokens[0] === 'nx') {
    tokens = tokens.slice(1);
  }

  if (tokens.length === 0) {
    return null;
  }

  const current = tokens[tokens.length - 1];
  const previousToken = tokens.length > 1 ? tokens[tokens.length - 2] : '';

  return { tokens, current, previousToken };
}
