/** yargs marks i18n strings with this prefix; we strip it before display. */
const YARGS_STRING_PREFIX = '__yargsString__:';

/**
 * Sanitizes a command/option description for use in completion output.
 *
 * - Strips the yargs i18n marker prefix `__yargsString__:` from the start.
 * - Collapses any literal TAB characters in the remaining string to spaces so
 *   they cannot break the value/description split understood by the shell.
 * - Returns '' for undefined or empty input.
 *
 * Colons that appear inside the description are left untouched.
 */
export function formatDescription(description: string | undefined): string {
  if (!description) {
    return '';
  }

  let result = description;
  if (result.startsWith(YARGS_STRING_PREFIX)) {
    result = result.slice(YARGS_STRING_PREFIX.length);
  }

  // Collapse literal tabs to spaces so they don't break the value/description
  // split (which is itself delimited by a TAB).
  result = result.replace(/\t/g, ' ');

  return result;
}

