 * environment variable) renders completion descriptions inline. Only `zsh` and
 * `fish` do; `bash`, `powershell`, `nushell`, and an unset `NX_COMPLETE` do not.
 */
export function shellRendersDescriptions(): boolean {
  const shell = process.env.NX_COMPLETE;
  return shell === 'zsh' || shell === 'fish';
}
