 * A dynamic or static completer for a single positional argument.
 */
export interface PositionalCompletion {
  /** Static list of allowed values, filtered by prefix. */
  choices?: string[];
  /** Dynamic completer, called with the partial value and the full token list. */
  complete?: (current: string, args: string[]) => string[];
}

/**
 * Completion metadata registered for a command path.
 */
export interface CompletionMetadata {
  /** Positional argument completers, indexed by positional position. */
  positionals?: PositionalCompletion[];
  /** Flag-value completers, keyed by flag name (aliases share a reference). */
  flags?: Record<string, (current: string, args: string[]) => string[]>;
}

/** Registry mapping a space-joined command path to its completion metadata. */
const registry = new Map<string, CompletionMetadata>();

/**
 * Registers completion metadata for a command path. The path is a
 * space-separated string of command tokens (e.g. `show target`).
 */
export function registerCompletion(
  path: string,
  metadata: CompletionMetadata
): void {
  registry.set(path, metadata);
}

/** True for tokens that look like a long flag (e.g. `--projects`). */
function isFlagToken(token: string): boolean {
  return token.startsWith('--');
}

/**
 * Searches the registry for the longest registered path that matches a prefix
 * of the given tokens. Flags (tokens starting with `--`) halt the prefix walk.
 *
 * @returns the matching metadata and the `positionalIndex` (count of non-flag
 * tokens typed beyond the matched path), or `null` when no path matches.
 */
export function findCompletionMetadata(
  tokens: string[]
): { metadata: CompletionMetadata; positionalIndex: number } | null {
  // The command path can only be built from the leading non-flag tokens.
  const leading: string[] = [];
  for (const token of tokens) {
    if (isFlagToken(token)) {
      break;
    }
    leading.push(token);
  }

  let matchedLength = 0;
  let metadata: CompletionMetadata | undefined;
  for (let length = leading.length; length >= 1; length--) {
    const key = leading.slice(0, length).join(' ');
    if (registry.has(key)) {
      matchedLength = length;
      metadata = registry.get(key);
      break;
    }
  }

  if (!metadata) {
    return null;
  }

  // Count every non-flag token beyond the matched command path — flags that
  // appear between/after positionals don't consume a positional slot.
  const nonFlagTotal = tokens.filter((token) => !isFlagToken(token)).length;
  const positionalIndex = nonFlagTotal - matchedLength;

  return { metadata, positionalIndex };
}

/**
 * Looks up the flag-value completion handler for a flag name in a metadata
 * object. Leading dashes on the flag name are ignored, so `--projects`,
 * `projects`, and `-p` all resolve consistently. Returns `null` when metadata
 * is null or the flag has no registered handler.
 */
export function findFlagCompletion(
  metadata: CompletionMetadata | null,
  flag: string
): ((current: string, args: string[]) => string[]) | null {
  if (!metadata || !metadata.flags) {
    return null;
  }
  const name = flag.replace(/^-+/, '');
  return metadata.flags[name] ?? null;
}

/**
 * Resolves completion candidates for a set of shell tokens.
 *
 * Flag dispatch takes precedence over positional dispatch:
 * - When `previousToken` is a long flag (`--foo`) and a handler is registered,
 *   the handler is called with `(current, tokens)`.
 * - When `previousToken` is a long flag but no handler is registered, returns
 *   `[]` (there is no fall-through to positionals).
 *
 * Otherwise dispatches to the positional completer for the position being
 * typed: calls its `complete(current, tokens)` or filters its `choices` by
 * prefix.
 *
 * @returns `null` for empty tokens, no metadata match, or a positional index
 * beyond the declared positionals.
 */
export function resolveCompletion(
  tokens: string[],
  current: string,
  previousToken: string
): string[] | null {
  if (!tokens || tokens.length === 0) {
    return null;
  }

  const match = findCompletionMetadata(tokens);
  if (!match) {
    return null;
  }

  const { metadata, positionalIndex } = match;

  // Flag dispatch takes precedence over positional dispatch.
  if (isFlagToken(previousToken)) {
    const handler = findFlagCompletion(metadata, previousToken);
    if (handler) {
      return handler(current, tokens);
    }
    // A recognized flag with no registered handler completes to nothing — we
    // must NOT fall through to positionals (the value belongs to the flag).
    return [];
  }

  // The last non-flag token is `current` (the value being typed), so the
  // positional slot being completed is one less than the count beyond the path.
  const index = positionalIndex - 1;
  const positionals = metadata.positionals ?? [];
  if (index < 0 || index >= positionals.length) {
    return null;
  }

  const positional = positionals[index];
  if (positional.complete) {
    return positional.complete(current, tokens);
  }
  if (positional.choices) {
    return positional.choices.filter((choice) => choice.startsWith(current));
  }
  return [];
}

/**
 * Test-only helper to clear the registry between test runs.
 * @internal
 */
export function __clearCompletionRegistry(): void {
  registry.clear();
