 * - invokes that binary with `NX_COMPLETE` set to the target shell name and
 *   `NX_VERBOSE_LOGGING` disabled, discarding stderr so diagnostic output can
 *   never corrupt the completion stream.
 */
export async function generateScript(shell: CompletionShell): Promise<string> {
  switch (shell) {
    case 'bash':
      return bashScript();
    case 'zsh':
      return zshScript();
    case 'fish':
      return fishScript();
    case 'powershell':
      return powershellScript();
    default:
