import * as yargs from 'yargs';
import { yargsAffectedCommand } from '../affected/command-object';
import { yargsGraphCommand } from '../graph/command-object';
import { yargsRunManyCommand } from '../run-many/command-object';
import { yargsWatchCommand } from '../watch/command-object';

/**
 * Returns a map from command name to its yargs handler object (which includes a
 * `builder` function). This is used to introspect which options each command
 * declares so that flag completions can be registered with every alias.
 */
export function getNxCommandHandlers(): Record<string, CommandModule> {
  return {
    'run-many': yargsRunManyCommand,
    affected: yargsAffectedCommand,
    graph: yargsGraphCommand,
    watch: yargsWatchCommand,
  };
}

/**
 * Runs a yargs builder function against a throwaway yargs instance and extracts
 * the declared option alias groups.
 *
 * @returns an object whose `aliases` Map maps each canonical option name to its
 * declared alias array, or `null` when the builder cannot be introspected.
 */
export function introspectBuilder(
  builder: (yargs: Argv) => Argv
): { aliases: Map<string, string[]> } | null {
  try {
    const instance = (yargs as any)([]) as Argv;
    const result = builder(instance) as any;

    const options =
      typeof result?.getOptions === 'function' ? result.getOptions() : null;
    const aliasRecord: Record<string, string[]> = options?.alias ?? {};

    const aliases = new Map<string, string[]>();
    for (const [canonical, list] of Object.entries(aliasRecord)) {
      aliases.set(canonical, list ?? []);
    }

    return { aliases };
  } catch {
    return null;
  }
}
