import { readModulePackageJson } from '../../utils/package-json';
import { getNxCommandHandlers, introspectBuilder } from './command-handlers';
import {
  completeGenerator,
  completeProjectTarget,
  getProjectNameCompletions,
  getProjectNamesWithTarget,
  getTargetNameCompletions,
} from './completion-providers';
import { registerCompletion } from './metadata';

type Completer = (current: string, args: string[]) => string[];

// Shared handler references, reused across commands so that a given kind of
// completion is always backed by the same function instance.
const completeProjects: Completer = (current) =>
  getProjectNameCompletions(current);
const completeTargets: Completer = (current) => getTargetNameCompletions(current);

/**
 * Builds a flags map for a command by introspecting its yargs builder for the
 * declared option aliases, then registering the given handler under each
 * canonical option name AND all of its aliases (sharing the same reference).
 */
function buildFlagCompletions(
  commandName: string,
  projectOptions: string[],
  targetOptions: string[]
): Record<string, Completer> {
  const handler = getNxCommandHandlers()[commandName];
  const introspected =
    handler && typeof handler.builder === 'function'
      ? introspectBuilder(handler.builder as any)
      : null;
  const aliases = introspected?.aliases ?? new Map<string, string[]>();

  const flags: Record<string, Completer> = {};
  const register = (canonical: string, completer: Completer) => {
    const names = new Set<string>([
      canonical,
      ...(aliases.get(canonical) ?? []),
    ]);
    for (const name of names) {
      flags[name] = completer;
    }
  };

  for (const option of projectOptions) {
    register(option, completeProjects);
  }
  for (const option of targetOptions) {
    register(option, completeTargets);
  }

  return flags;
}

/**
 * Returns the `@nx/*` package names declared in the nx package's
 * `nx-migrations.packageGroup`. Returns [] when the nx package.json cannot be
 * read.
 */
function getNxPackageGroup(): string[] {
  let packageJson: any;
  try {
    packageJson = readModulePackageJson('nx').packageJson;
  } catch {
    try {
      packageJson = readJsonFile(join(__dirname, '../../../package.json'));
    } catch {
      return [];
    }
  }

  const group: Array<string | { package?: string }> =
    packageJson?.['nx-migrations']?.packageGroup ?? [];

  const names: string[] = [];
  for (const entry of group) {
    const name = typeof entry === 'string' ? entry : entry?.package;
    if (name && name.startsWith('@nx/')) {
      names.push(name);
    }
  }
  return names;
}

// --- Positional completions ------------------------------------------------

// nx run <project:target>
registerCompletion('run', {
  positionals: [{ complete: (current) => completeProjectTarget(current) }],
});

// nx generate <plugin:generator> — the `g` alias shares the same metadata.
const generateMetadata = {
  positionals: [{ complete: (current: string) => completeGenerator(current) }],
};
registerCompletion('generate', generateMetadata);
registerCompletion('g', generateMetadata);

// nx show project <projectName>
registerCompletion('show project', {
  positionals: [{ complete: (current) => getProjectNameCompletions(current) }],
});

// nx show target <project:target | inputs | outputs>
registerCompletion('show target', {
  positionals: [
    {
      complete: (current) => {
        const fixed = ['inputs', 'outputs'].filter((choice) =>
          choice.startsWith(current)
        );
        return [...completeProjectTarget(current), ...fixed];
      },
    },
  ],
});

// nx show target inputs <project:target>
registerCompletion('show target inputs', {
  positionals: [{ complete: (current) => completeProjectTarget(current) }],
});

// nx show target outputs <project:target>
registerCompletion('show target outputs', {
  positionals: [{ complete: (current) => completeProjectTarget(current) }],
});

// nx add <@nx/* package>
registerCompletion('add', {
  positionals: [
    {
      complete: (current) =>
        getNxPackageGroup().filter((name) => name.startsWith(current)),
    },
  ],
});

// --- Flag completions ------------------------------------------------------

registerCompletion('run-many', {
  flags: buildFlagCompletions('run-many', ['projects'], ['targets']),
});

registerCompletion('affected', {
  flags: buildFlagCompletions('affected', ['projects', 'exclude'], ['targets']),
});

const graphFlags = {
  flags: buildFlagCompletions('graph', ['focus', 'exclude'], ['targets']),
};
registerCompletion('graph', graphFlags);
// `dep-graph` is a yargs alias of `graph`; share the same metadata.
registerCompletion('dep-graph', graphFlags);

registerCompletion('watch', {
  flags: buildFlagCompletions('watch', ['projects'], []),
});

// --- Infix (conventional) target completions -------------------------------
// `nx <target> <TAB>` completes project names that declare <target>.
const CONVENTIONAL_TARGETS = ['build', 'test', 'lint', 'serve'];
for (const target of CONVENTIONAL_TARGETS) {
  registerCompletion(target, {
    positionals: [
      { complete: (current) => getProjectNamesWithTarget(current, target) },
    ],
  });
}
