import { resolveCompletion } from './metadata';
// Importing the registrations module for its side effects ensures every
// supported command path is registered before we attempt to resolve.
import './registrations';

/**
 * Fast-path completion entry point.
 *
 * Parses `argv` (a `process.argv`-style array) into shell tokens and resolves
 * completion candidates against the registered command metadata.
 *
 * @returns `false` when there are no tokens to complete or when no registered
 * metadata matches (so the caller can fall back to another completion path).
 * Otherwise writes each candidate on its own line via `console.log` and returns
 * `true` (an empty candidate list still returns `true`).
 */
export function tryValueCompletion(argv: string[]): boolean {
  const parsed = parseCompletionArgs(argv);
  if (!parsed) {
    return false;
  }

  const { tokens, current, previousToken } = parsed;
  const completions = resolveCompletion(tokens, current, previousToken);
  if (completions === null) {
    return false;
  }

  for (const completion of completions) {
    console.log(completion);
  }
  return true;
}
