const SHELLS = ['bash', 'zsh', 'fish', 'powershell'] as const;

export const yargsCompletionCommand: CommandModule = {
  command: 'completion [shell]',
  describe:
    'Print a shell completion script. Source the output from your shell profile to enable Tab completion for nx.',
  builder: (yargs) =>
    yargs
      .positional('shell', {
        type: 'string',
        describe:
          'The shell to generate a completion script for. Defaults to the shell that requested completions.',
        choices: SHELLS as unknown as string[],
      })
      .example(
        'source <($0 completion bash)',
        'Enable nx completion for the current bash session'
      )
      .example(
