/**
 * Reads the cached project graph, returning `null` (rather than throwing) when
 * it is unavailable. Completion must never crash the shell, so every provider
 * degrades gracefully to an empty result.
 */
function safeReadProjectGraph(): ProjectGraph | null {
  try {
    return readCachedProjectGraph();
  } catch {
    return null;
  }
}

/**
 * Returns all project names from the cached project graph that start with the
 * given prefix. Returns [] when the project graph is unavailable.
 */
export function getProjectNameCompletions(prefix: string): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  return Object.keys(graph.nodes).filter((name) => name.startsWith(prefix));
}

/**
 * Returns project names that start with the given prefix AND declare a target
 * matching the given target name. Returns [] for nonexistent targets or when
 * the graph is unavailable.
 */
export function getProjectNamesWithTarget(
  prefix: string,
  target: string
): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  return Object.keys(graph.nodes).filter((name) => {
    if (!name.startsWith(prefix)) {
      return false;
    }
    const targets = graph.nodes[name]?.data?.targets ?? {};
    return !!targets[target];
  });
}

/**
 * Returns unique target names across all workspace projects that start with the
 * given prefix. Returns [] when the graph is unavailable.
 */
export function getTargetNameCompletions(prefix: string): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  const targets = new Set<string>();
  for (const node of Object.values(graph.nodes)) {
    for (const targetName of Object.keys(node?.data?.targets ?? {})) {
      if (targetName.startsWith(prefix)) {
        targets.add(targetName);
      }
    }
  }
  return [...targets];
}

/**
 * Returns target names for a specific project that start with the given prefix.
 * If the project name is not found in the graph, falls back to all workspace
 * target names — this supports partial project-name typing scenarios such as
 * `proj:t<TAB>` where `proj` is not (yet) a complete project name.
 */
export function getTargetNamesForProject(
  prefix: string,
  projectName: string
): string[] {
  const graph = safeReadProjectGraph();
  if (!graph) {
    return [];
  }
  const node = graph.nodes[projectName];
  if (!node) {
    return getTargetNameCompletions(prefix);
  }
  return Object.keys(node.data?.targets ?? {}).filter((targetName) =>
    targetName.startsWith(prefix)
  );
}

/**
 * Two-stage completion for `project:target` tokens.
 *
 * Stage 1 (no colon in `current`): returns matching project names, each
 * suffixed with `:` so the shell keeps completing into the target segment.
 *
 * Stage 2 (colon present in `current`): returns `projectName:targetName`
 * candidates matching the portion after the colon, falling back to all
 * workspace targets when the project name is unknown.
 */
export function completeProjectTarget(current: string): string[] {
  const colonIndex = current.indexOf(':');

  if (colonIndex === -1) {
    return getProjectNameCompletions(current).map((name) => `${name}:`);
  }

  const projectName = current.slice(0, colonIndex);
  const targetPrefix = current.slice(colonIndex + 1);

  return getTargetNamesForProject(targetPrefix, projectName).map(
    (targetName) => `${projectName}:${targetName}`
  );
}

/**
 * Resolves the `package.json` of a candidate generator plugin, either from
 * `node_modules` or from a workspace-local project. Returns `null` when the
 * plugin cannot be resolved.
 */
function resolvePluginPackageJson(
  pluginName: string,
  graph: ProjectGraph | null
): { packageJson: any; dir: string } | null {
  // Prefer resolving from node_modules (published plugins).
  try {
    const { packageJson, path } = readModulePackageJson(pluginName);
    return { packageJson, dir: dirname(path) };
  } catch {
    // fall through to workspace-local resolution
  }

  // Fall back to a workspace-local project that happens to be a plugin.
  const node = graph?.nodes?.[pluginName];
  if (node?.data?.root) {
    try {
      const packageJsonPath = join(
        workspaceRoot,
        node.data.root,
        'package.json'
      );
      const packageJson = readJsonFile(packageJsonPath);
      return { packageJson, dir: dirname(packageJsonPath) };
    } catch {
      // ignore
    }
  }

  return null;
}

/**
 * Returns plugin names (from `devDependencies` in the root `package.json` AND
 * from project-graph nodes) that declare a `generators` field and whose name
 * starts with the given prefix. Returns [] when the root `package.json` is
 * missing.
 */
export function getGeneratorPluginCompletions(prefix: string): string[] {
  let rootPackageJson: any;
  try {
    rootPackageJson = readJsonFile(join(workspaceRoot, 'package.json'));
  } catch {
    return [];
  }

  const graph = safeReadProjectGraph();

  const candidates = new Set<string>();
  for (const dep of Object.keys(rootPackageJson.devDependencies ?? {})) {
    candidates.add(dep);
  }
  if (graph) {
    for (const name of Object.keys(graph.nodes)) {
      candidates.add(name);
    }
  }

  const results: string[] = [];
  for (const name of candidates) {
    if (!name.startsWith(prefix)) {
      continue;
    }
    const resolved = resolvePluginPackageJson(name, graph);
    if (!resolved) {
      continue;
    }
    const { packageJson } = resolved;
    if (packageJson.generators ?? packageJson.schematics) {
      results.push(name);
    }
  }

  return results;
}

/**
 * Returns generator names for a plugin that are not marked hidden and whose
 * name starts with the given prefix. Returns [] when the plugin's
 * `package.json` (or its generators collection) is malformed or missing.
 */
export function getGeneratorsForPlugin(
  pluginName: string,
  prefix: string
): string[] {
  try {
    const resolved = resolvePluginPackageJson(
      pluginName,
      safeReadProjectGraph()
    );
    if (!resolved) {
      return [];
    }

    const { packageJson, dir } = resolved;
    const generatorsFile = packageJson.generators ?? packageJson.schematics;
    if (!generatorsFile) {
      return [];
    }

    const generatorsJson = readJsonFile(join(dir, generatorsFile));
    const collection = {
      ...(generatorsJson.generators ?? {}),
      ...(generatorsJson.schematics ?? {}),
    };

    return Object.entries(collection)
      .filter(
        ([name, generator]: [string, any]) =>
          !generator?.hidden && name.startsWith(prefix)
      )
      .map(([name]) => name);
  } catch {
    return [];
  }
}

